{"path": "verify.mjs", "content": "import assert from 'node:assert/strict';
import { DEFAULT_OPTIONS } from './defaults.mjs';
import { resolveOptions } from './resolver.mjs';
import { formatValue } from './formatter.mjs';

// Defaults
assert.deepEqual(DEFAULT_OPTIONS, { precision: 2, prefix: '', unitLabel: '' });

// Old behavior
assert.equal(formatValue(12.345), '12.35');
assert.equal(formatValue(12.34, { precision: 1, prefix: '~' }), '~12.3');

// New option
assert.equal(formatValue(12.3, { unitLabel: 'kg' }), '12.30 kg');
assert.equal(formatValue(12.3, { precision: 1, prefix: '~', unitLabel: 'kg' }), '~12.3 kg');

// resolveOptions fresh objects
assert.deepEqual(resolveOptions(), { precision: 2, prefix: '', unitLabel: '' });
assert.deepEqual(resolveOptions({ unitLabel: 'kg' }), { precision: 2, prefix: '', unitLabel: 'kg' });
const a = resolveOptions();
const b = resolveOptions();
assert.notEqual(a, b);
a.precision = 4;
assert.equal(DEFAULT_OPTIONS.precision, 2);
assert.equal(b.precision, 2);

// DEFAULT_OPTIONS never mutated
formatValue(1, { precision: 4, prefix: 'x', unitLabel: 'y' });
assert.deepEqual(DEFAULT_OPTIONS, { precision: 2, prefix: '', unitLabel: '' });

// undefined means no overrides
assert.deepEqual(resolveOptions(undefined), { precision: 2, prefix: '', unitLabel: '' });

// Reject non-object/null/array
for (const bad of [null, 5, 'x', true, [], [1]]) {
  assert.throws(() => resolveOptions(bad), TypeError);
}

// Reject unknown keys
assert.throws(() => resolveOptions({ foo: 1 }), TypeError);

// Precision validation
assert.throws(() => resolveOptions({ precision: 5 }), RangeError);
assert.throws(() => resolveOptions({ precision: -1 }), RangeError);
assert.throws(() => resolveOptions({ precision: 1.5 }), TypeError);
assert.throws(() => resolveOptions({ precision: '2' }), TypeError);
assert.equal(resolveOptions({ precision: 0 }).precision, 0);
assert.equal(resolveOptions({ precision: 4 }).precision, 4);

// prefix/unitLabel type validation
assert.throws(() => resolveOptions({ prefix: 1 }), TypeError);
assert.throws(() => resolveOptions({ unitLabel: 1 }), TypeError);

// formatValue finite number only
for (const bad of [NaN, Infinity, -Infinity, '1', null, undefined, {}]) {
  assert.throws(() => formatValue(bad), TypeError);
}

// formatValue delegates to resolveOptions (validation propagates)
assert.throws(() => formatValue(1, { foo: 1 }), TypeError);
assert.throws(() => formatValue(1, { precision: 9 }), RangeError);

// No shared mutable state between calls
const r1 = resolveOptions({ unitLabel: 'kg' });
const r2 = resolveOptions({ unitLabel: 'kg' });
assert.notEqual(r1, r2);

console.log('All checks passed');
"}

